export function filterMarketplace(params){const price=params.get('budget');const max=price===null||price===''?Infinity:Number(price);if(Number.isNaN(max)||max<0)return [];const q=(params.get('q')||'').toLowerCase();return marketplaceListings.filter(p=>p.price<=max&&(!params.get('platform')||params.get('platform')==='all'||p.platform===params.get('platform'))&&(!params.get('category')||params.get('category')==='all'||p.category===params.get('category'))&&(params.get('available')!=='true'||p.status==='Available')&&(params.get('portable')!=='true'||p.portable)&&`${p.name} ${p.condition} ${p.area}`.toLowerCase().includes(q));}
